import React, { useState } from 'react';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import { useToast } from '../../contexts/ToastContext';
import { useSelector } from 'react-redux';
import { cn } from '../../utils/cn';

const cupPrice = 500;

const paymentMethods = [
    {
        key: 'paystack',
        label: 'Paystack',
        color: 'blue',
        icon: 'CreditCard',
        gradient: 'from-blue-600 to-blue-500',
        bg: 'bg-blue-500/10',
        border: 'border-blue-500/30',
        text: 'text-blue-400',
        shadow: 'shadow-blue-500/20',
    },
];

const BuyCoffee = () => {
    const [cupCount, setCupCount] = useState(1);
    const [isProcessing, setIsProcessing] = useState(false);
    const { user } = useSelector(state => state.auth);
    const { addToast } = useToast();
    const method = paymentMethods[0];

    const loadPaystackScript = () => {
        return new Promise((resolve, reject) => {
            if (window.PaystackPop) {
                resolve(window.PaystackPop);
                return;
            }
            const existing = document.getElementById('paystack-script');
            if (existing) {
                existing.addEventListener('load', () => resolve(window.PaystackPop));
                existing.addEventListener('error', () => reject(new Error('Failed to load Paystack')));
                return;
            }
            const script = document.createElement('script');
            script.src = 'https://js.paystack.co/v1/inline.js';
            script.id = 'paystack-script';
            script.onload = () => resolve(window.PaystackPop);
            script.onerror = () => reject(new Error('Failed to load Paystack'));
            document.body.appendChild(script);
        });
    };

    const handlePaystackPayment = async () => {
        if (!user || !user.email) {
            addToast('Please log in to pay with Paystack', 'error');
            return;
        }

        let PaystackPop;
        try {
            PaystackPop = await loadPaystackScript();
        } catch (err) {
            addToast('Failed to load payment system. Please refresh and try again.', 'error');
            return;
        }

        if (!PaystackPop) {
            addToast('Payment system unavailable. Please try again.', 'error');
            return;
        }

        const pk = import.meta.env.VITE_PAYSTACK_PUBLIC_KEY;
        if (!pk || pk === 'your-paystack-public-key-here') {
            addToast('Payment is not configured yet. Please contact support.', 'error');
            return;
        }

        setIsProcessing(true);
        const amount = cupCount * cupPrice;

        const handler = PaystackPop.setup({
            key: pk,
            email: user.email,
            amount: amount * 100,
            currency: 'NGN',
            ref: `LUC-COFFEE-${user.id.slice(0, 8)}-${Date.now()}`,
            metadata: {
                custom_fields: [
                    { display_name: 'Type', variable_name: 'type', value: 'buy_coffee' },
                    { display_name: 'User ID', variable_name: 'user_id', value: user.id },
                    { display_name: 'Cups', variable_name: 'cups', value: String(cupCount) },
                ],
            },
            callback: function (response) {
                setIsProcessing(false);
                addToast(`Thank you! Payment of ₦${amount.toLocaleString()} confirmed (${response.reference}).`, 'success');
            },
            onClose: function () {
                setIsProcessing(false);
                addToast('Payment cancelled.', 'info');
            },
        });

        handler.openIframe();
    };

    return (
        <div className="min-h-screen bg-[#0a0f1a] flex flex-col transition-colors duration-300">
            <Helmet>
                <title>Buy LUC Hub a Coffee | Support Our Mission</title>
                <meta name="description" content="Support LUC Hub by buying us a coffee. Your support helps us keep the platform free and accessible for everyone." />
            </Helmet>

            <Header />

            <main className="flex-1 relative overflow-hidden">
                {/* Background glows */}
                <div className="absolute inset-0 pointer-events-none">
                    <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-cyan-500/8 blur-[120px] rounded-full" />
                    <div className="absolute bottom-[10%] right-[-5%] w-[35%] h-[35%] bg-amber-500/8 blur-[100px] rounded-full" />
                    <div className="absolute top-[20%] right-[10%] w-[30%] h-[30%] bg-blue-600/5 blur-[120px] rounded-full" />
                </div>

                <div className="pb-20 px-6 md:px-8 relative z-10">
                    <div className="max-w-4xl mx-auto flex flex-col">
                        <div className="h-28 md:h-20" />

                        {/* Hero */}
                        <div className="text-center animate-in fade-in slide-in-from-bottom-4 duration-1000 px-2">
                            <div className="inline-flex items-center justify-center w-24 h-24 rounded-[2rem] bg-amber-500/10 text-amber-500 mb-8 shadow-2xl shadow-amber-500/10 rotate-3 hover:rotate-0 transition-transform duration-500">
                                <Icon name="Coffee" size={44} />
                            </div>
                            <h1 className="text-4xl md:text-6xl font-black text-white mb-6 tracking-tight leading-[1.1]">
                                Fuel the <span className="text-amber-500">LUC</span> Mission
                            </h1>
                            <p className="text-lg text-slate-400 max-w-2xl mx-auto leading-relaxed">
                                LUC is built with love to empower our community. Every coffee keeps the mission alive!
                            </p>
                        </div>

                        <div className="h-20" />

                        <div className="flex flex-col lg:grid lg:grid-cols-12 gap-12 items-start pb-20">
                            {/* Left: Cup Picker + Bank Details */}
                            <div className="w-full max-w-[520px] lg:max-w-none mx-auto lg:col-span-7 space-y-6 animate-in fade-in slide-in-from-left-6 duration-1000 delay-200">

                                {/* Cup selector */}
                                <div className="bg-white/5 border border-white/10 rounded-[2rem] p-7 space-y-6">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/40">How many coffees?</p>
                                    <div className="flex flex-wrap gap-3">
                                        {[1, 3, 5].map(num => (
                                            <button
                                                key={num}
                                                type="button"
                                                onClick={() => setCupCount(num)}
                                                className={cn(
                                                    "flex-1 min-w-[80px] h-14 rounded-2xl border-2 font-black transition-all duration-300 flex items-center justify-center gap-2",
                                                    cupCount === num
                                                        ? "bg-amber-500 border-amber-500 text-white shadow-xl shadow-amber-500/20 scale-105"
                                                        : "bg-white/5 border-white/10 text-white/50 hover:border-amber-500/30 hover:text-white"
                                                )}
                                            >
                                                <span className="text-xl">☕</span>
                                                <span>x{num}</span>
                                            </button>
                                        ))}
                                        <div className={cn(
                                            "flex-1 min-w-[80px] h-14 rounded-2xl border-2 transition-all duration-300 flex items-center justify-center gap-1 px-3",
                                            "bg-white/5 border-white/10"
                                        )}>
                                            <span className="text-white/40 font-black text-sm">×</span>
                                            <input
                                                type="number"
                                                min="1"
                                                max="999"
                                                value={cupCount}
                                                onChange={e => setCupCount(Math.max(1, parseInt(e.target.value) || 1))}
                                                className="bg-transparent border-none outline-none w-full text-center font-black text-white text-lg"
                                                style={{ colorScheme: 'dark' }}
                                            />
                                        </div>
                                    </div>

                                    {/* Total */}
                                    <div className="flex items-center justify-between p-4 bg-amber-500/5 border border-amber-500/20 rounded-2xl">
                                        <div className="flex items-center gap-2 text-amber-400 font-black text-sm uppercase tracking-widest">
                                            <Icon name="Coffee" size={16} />
                                            Total Support
                                        </div>
                                        <span className="text-2xl font-black text-amber-400">
                                            ₦{(cupCount * cupPrice).toLocaleString()}
                                        </span>
                                    </div>
                                </div>

                                {/* Payment card */}
                                <div className={cn(
                                    "bg-gradient-to-br from-slate-900 to-slate-800 border rounded-[2rem] p-7 space-y-5 transition-all duration-500",
                                    method.border
                                )}>
                                    <div className="flex items-center gap-3 mb-2">
                                        <div className={cn("w-10 h-10 rounded-full flex items-center justify-center", method.bg)}>
                                            <Icon name="ShieldCheck" size={20} className={method.text} />
                                        </div>
                                        <div>
                                            <p className={cn("text-[10px] font-black uppercase tracking-widest", method.text)}>
                                                Paystack · Secure Payment
                                            </p>
                                            <p className="text-xs text-white/40 font-medium">Pay instantly with card or bank transfer</p>
                                        </div>
                                    </div>

                                    <div className={cn(
                                        "flex items-center justify-between p-4 rounded-2xl border",
                                        method.bg, method.border
                                    )}>
                                        <p className={cn("text-xs font-black uppercase tracking-widest", method.text)}>Amount to Pay</p>
                                        <p className={cn("text-xl font-black", method.text)}>
                                            ₦{(cupCount * cupPrice).toLocaleString()}
                                        </p>
                                    </div>

                                    <button
                                        onClick={handlePaystackPayment}
                                        disabled={isProcessing}
                                        className={cn(
                                            "w-full h-14 rounded-2xl font-black text-sm transition-all duration-300 flex items-center justify-center gap-2",
                                            isProcessing
                                                ? "bg-white/10 text-white/40 cursor-not-allowed"
                                                : "bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-xl shadow-blue-500/20 hover:scale-[1.02] active:scale-[0.98]"
                                        )}
                                    >
                                        {isProcessing ? (
                                            <>
                                                <Icon name="Loader2" size={18} className="animate-spin" />
                                                Processing...
                                            </>
                                        ) : (
                                            <>
                                                <Icon name="Lock" size={16} />
                                                Pay ₦{(cupCount * cupPrice).toLocaleString()} with Paystack
                                            </>
                                        )}
                                    </button>

                                    <div className={cn(
                                        "p-4 rounded-2xl border text-center",
                                        method.bg, method.border
                                    )}>
                                        <p className={cn("text-xs font-bold", method.text)}>
                                            Your payment is secured by Paystack. You'll receive instant confirmation after payment.
                                        </p>
                                    </div>
                                </div>
                            </div>

                            {/* Right: Impact sidebar */}
                            <div className="w-full max-w-[520px] lg:max-w-none mx-auto lg:col-span-5 space-y-8 animate-in fade-in slide-in-from-right-6 duration-1000 delay-400">
                                <div className="bg-white/5 border border-white/10 rounded-[2.5rem] p-8 md:p-10 relative overflow-hidden group">
                                    <div className="absolute -top-10 -right-10 w-40 h-40 bg-amber-500/5 rounded-full blur-3xl group-hover:bg-amber-500/10 transition-all duration-700" />
                                    <h3 className="text-xl font-black mb-8 flex items-center justify-center gap-3 text-white">
                                        <Icon name="ShieldCheck" size={26} className="text-amber-500" />
                                        The Impact
                                    </h3>
                                    <ul className="space-y-7">
                                        {[
                                            { title: 'Server Infrastructure', desc: 'Keep our systems running fast and reliable 24/7.', icon: 'Server' },
                                            { title: 'Community Features', desc: 'Fund development of interactive and matching tools.', icon: 'Users' },
                                            { title: 'Data Quality', desc: 'Source and verify the highest quality opportunities.', icon: 'Activity' },
                                        ].map((item, i) => (
                                            <li key={i} className="flex items-start gap-5 group/item">
                                                <div className="shrink-0 w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-amber-500 transition-transform group-hover/item:scale-110">
                                                    <Icon name={item.icon} size={20} />
                                                </div>
                                                <div className="flex-1 pt-1">
                                                    <h4 className="font-bold text-base mb-1 text-white">{item.title}</h4>
                                                    <p className="text-sm text-white/50 leading-relaxed">{item.desc}</p>
                                                </div>
                                            </li>
                                        ))}
                                    </ul>
                                </div>

                                {/* How it works */}
                                <div className="bg-white/5 border border-white/10 rounded-[2.5rem] p-8 space-y-4">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-white/40 text-center">How it works</p>
                                    {[
                                        { step: '1', text: 'Pick how many coffees you want to send.' },
                                        { step: '2', text: 'Click the Paystack button to pay securely.' },
                                        { step: '3', text: 'Complete payment with your card or bank transfer.' },
                                        { step: '4', text: 'Receive instant confirmation. Thank you! ☕' },
                                    ].map((item, i) => (
                                        <div key={i} className="flex items-start gap-4">
                                            <div className="w-7 h-7 shrink-0 rounded-full bg-amber-500/10 flex items-center justify-center">
                                                <span className="text-[11px] font-black text-amber-400">{item.step}</span>
                                            </div>
                                            <p className="text-sm text-white/60 leading-relaxed pt-0.5">{item.text}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default BuyCoffee;
